  max-width: 220px !important;
}
.placeholder-laptop {
  background: linear-gradient(135deg, #b0b0b8 0%, #909098 100%);
  border-radius: 12px;
  width: 80% !important;
  aspect-ratio: 16/10 !important;
  max-width: 400px !important;
}
.placeholder-tablet {
  background: linear-gradient(135deg, #2a2a2e 0%, #404045 100%);
  border-radius: 16px;
  width: 60% !important;
  aspect-ratio: 3/4 !important;
  max-width: 280px !important;
}
.placeholder-earbuds {
  background: linear-gradient(135deg, #e0d8f0 0%, #c8bcd8 100%);
  border-radius: 50%;
  width: 45% !important;
  aspect-ratio: 1 !important;
  max-width: 200px !important;
}
.placeholder-tradein {
  background: linear-gradient(135deg, #b8d0e8 0%, #90b8d8 100%);
  border-radius: 20px;
