  align-items: center;
  justify-content: center;
  background: var(--bg-secondary);
}
.info-card .card-body {
  padding: var(--card-padding);
}
.info-card .card-icon-large {
  font-size: 48px;
  margin-bottom: 8px;
}
.info-card .card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.3;
}
.info-card .card-desc {
