}

/* --- Product Icon Bar --- */
.product-icon-bar {
  padding: 20px 0;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-primary);
}
.product-icon-bar .icon-bar-scroll {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  justify-content: center;
  flex-wrap: nowrap;
}
.product-icon-bar .icon-bar-scroll::-webkit-scrollbar { display: none; }
.icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 20px;
  min-width: 90px;
  transition: opacity var(--transition-fast);
  cursor: pointer;
  text-decoration: none;
  color: var(--text-primary);
}
.icon-item:hover { opacity: 0.7; text-decoration: none; }
.icon-item .icon-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
