  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.experience-card .exp-placeholder {
  width: 240px;
  height: 180px;
  background: linear-gradient(135deg, var(--border-light), var(--border-color));
  border-radius: var(--radius-md);
}

/* --- Special Stores Section --- */
.special-stores {
  padding: var(--section-padding);
  background: var(--bg-primary);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
  .product-tile {
    min-height: 500px;
  }
  .entertainment-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .brand-collab-card {
    flex-direction: column;
    padding: 40px 30px;
    gap: 30px;
  }
  .experience-card {
    flex-direction: column;
    padding: 40px 30px;
    gap: 30px;
  }
  .footer-nav-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --nav-height: 44px;
  }

  .hero-section h1 { font-size: 36px; }
  .hero-section .hero-subtitle { font-size: 19px; }
  .category-hero h1 { font-size: 32px; }
  .section-heading h2 { font-size: 28px; }
  .section-heading .section-subtitle { font-size: 17px; }

  .top-nav .nav-links { display: none; }
  .top-nav .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(255,255,255,0.98);
    backdrop-filter: blur(20px);
    padding: 16px 22px;
    gap: 14px;
    border-bottom: 1px solid var(--border-light);
    z-index: 999;
  }
  .top-nav .nav-links.open a { font-size: 15px; }
  .nav-toggle { display: flex; }

  .product-tile { min-height: 420px; padding: 30px 20px 0; }
  .product-tile .tile-title { font-size: 28px; }
  .product-tile .tile-tagline { font-size: 17px; }
  .product-tile .tile-ctas { gap: 14px; }
  .product-tile .tile-ctas a { font-size: 15px; }

  .product-card { flex: 0 0 240px; }
  .info-card { flex: 0 0 260px; }
  .savings-card { flex: 0 0 240px; }

  .entertainment-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .carousel-track { padding: 0 16px; }
  .carousel-header { padding: 0 16px; }

  .brand-collab-card {
    padding: 30px 20px;
  }
  .brand-collab-card .collab-heading { font-size: 28px; }
  .brand-collab-card .collab-subtitle { font-size: 17px; }

  .experience-card {
    padding: 30px 20px;
  }
  .experience-card .exp-title { font-size: 24px; }

  /* Footer accordion on mobile */
  .footer-nav-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-nav-col {
    border-bottom: 1px solid var(--border-light);
  }
  .footer-nav-col h4 {
    padding: 12px 0;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    user-select: none;
  }
  .footer-nav-col h4::after {
    content: '';
    width: 10px;
    height: 10px;
    border-right: 1.5px solid var(--text-secondary);
    border-bottom: 1.5px solid var(--text-secondary);
    transform: rotate(45deg);
    transition: transform var(--transition-fast);
    flex-shrink: 0;
  }
  .footer-nav-col.expanded h4::after {
    transform: rotate(-135deg);
  }
  .footer-nav-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-base);
    padding: 0;
  }
  .footer-nav-col.expanded ul {
    max-height: 500px;
    padding-bottom: 12px;
  }
  .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }

  .hero-section { padding: 50px 0 40px; }
  .section-nav .section-tab { font-size: 11px; padding: 10px 12px; }
  .icon-item { padding: 8px 12px; min-width: 72px; }
  .icon-item .icon-circle { width: 42px; height: 42px; font-size: 16px; }
}

@media (max-width: 480px) {
  .entertainment-grid {
    grid-template-columns: 1fr 1fr;
  }
  .product-tile .tile-title { font-size: 24px; }
  .product-tile .tile-tagline { font-size: 15px; }
}

/* ============================================
   Orchard — Premium Tech E-Commerce Store
   Design System & Component Styles
   ============================================ */

/* --- Design Tokens --- */
:root {
  --bg-primary: #ffffff;
  --bg-secondary: #f5f5f7;
  --bg-tertiary: #fbfbfd;
  --text-primary: #1d1d1f;
  --text-secondary: #6e6e73;
  --text-tertiary: #86868b;
  --accent-blue: #0066cc;
  --accent-blue-hover: #004499;
  --border-color: #d2d2d7;
  --border-light: #e8e8ed;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.12);
  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 24px;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --nav-height: 48px;
  --section-padding: 60px 0;
  --card-padding: 24px;
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease-out;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-stack);
  font-size: 17px;
  line-height: 1.47;
  color: var(--text-primary);
  background: var(--bg-primary);
  overflow-x: hidden;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--accent-blue-hover); text-decoration: underline; }

img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Utility --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); border: 0;
}

.text-secondary { color: var(--text-secondary); }
.text-tertiary { color: var(--text-tertiary); }
.text-accent { color: var(--accent-blue); }
.text-center { text-align: center; }

/* --- Ribbon Banner --- */
.ribbon-banner {
  background: var(--bg-secondary);
  text-align: center;
  padding: 12px 22px;
  font-size: 14px;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-light);
}
.ribbon-banner a {
  color: var(--accent-blue);
  white-space: nowrap;
}

/* --- Top Navigation --- */
.top-nav {
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--nav-height);
}
.top-nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}
.top-nav .nav-logo {
  font-size: 20px;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}
.top-nav .nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
}
.top-nav .nav-links a {
  font-size: 12px;
  color: var(--text-primary);
  opacity: 0.8;
  transition: opacity var(--transition-fast);
  letter-spacing: 0;
}
.top-nav .nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}
.top-nav .nav-links a.active {
  opacity: 1;
  font-weight: 500;
}

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}
.nav-toggle span {
  display: block;
  width: 18px;
  height: 1.5px;
  background: var(--text-primary);
  transition: var(--transition-fast);
}

/* --- Hero Section --- */
.hero-section {
  padding: 80px 0 60px;
  text-align: center;
  background: var(--bg-primary);
}
.hero-section h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.07;
  margin-bottom: 8px;
}
.hero-section .hero-subtitle {
  font-size: 28px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: 20px;
  letter-spacing: -0.01em;
}
.hero-ctas {
  display: flex;
  gap: 24px;
  justify-content: center;
  flex-wrap: wrap;
}
.hero-ctas a {
  font-size: 17px;
  font-weight: 400;
}

/* --- Category Hero (Shop Pages) --- */
.category-hero {
  padding: 60px 0 40px;
  text-align: center;
  background: var(--bg-primary);
}
.category-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.08;
  margin-bottom: 6px;
}

/* --- Section Headings --- */
.section-heading {
  margin-bottom: 4px;
}
.section-heading h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}
.section-heading .section-subtitle {
  font-size: 21px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-top: 4px;
  letter-spacing: 0;
}
.section-heading .section-promo {
  font-size: 14px;
  color: var(--text-secondary);
  margin-top: 6px;
}
.section-heading .section-promo a {
  color: var(--accent-blue);
}

/* --- Product Grid (Homepage) --- */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 12px 0;
}
.product-tile {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 580px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 40px 30px 0;
  transition: transform var(--transition-base);
}
.product-tile:hover {
  transform: scale(1.005);
}
.product-tile .tile-content {
  position: relative;
  z-index: 2;
}
.product-tile .tile-badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.product-tile .tile-title {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: 4px;
}
.product-tile .tile-tagline {
  font-size: 21px;
  color: var(--text-secondary);
  margin-bottom: 16px;
  font-weight: 400;
}
.product-tile .tile-ctas {
  display: flex;
  gap: 20px;
  justify-content: center;
  margin-bottom: 24px;
}
.product-tile .tile-ctas a {
  font-size: 17px;
}
.product-tile .tile-image {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  position: relative;
  z-index: 1;
}
.product-tile .tile-image .product-placeholder {
  width: 70%;
  max-width: 380px;
  aspect-ratio: 3/4;
  border-radius: var(--radius-md);
  margin-bottom: -2px;
}

/* Tile background colors */
.tile-phone { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); color: var(--text-primary); }
.tile-laptop-neo { background: linear-gradient(180deg, #fbfbfd 0%, #eef0f2 100%); color: var(--text-primary); }
.tile-tablet-pro { background: linear-gradient(180deg, #1d1d1f 0%, #2d2d30 100%); color: #fff; }
.tile-tablet-pro .tile-tagline { color: rgba(255,255,255,0.7); }
.tile-laptop-pro { background: linear-gradient(180deg, #1d1d1f 0%, #2d2d30 100%); color: #fff; }
.tile-laptop-pro .tile-tagline { color: rgba(255,255,255,0.7); }
.tile-earbuds { background: linear-gradient(180deg, #f5f0ff 0%, #e8e0f5 100%); color: var(--text-primary); }
.tile-tradein { background: linear-gradient(180deg, #f0f7ff 0%, #ddeaf8 100%); color: var(--text-primary); }

/* Product placeholder shapes */
.placeholder-phone {
  background: linear-gradient(135deg, #c0c0c5 0%, #a0a0a8 50%, #888890 100%);
  border-radius: 30px;
  width: 55% !important;
  aspect-ratio: 9/19 !important;
  max-width: 220px !important;
}
.placeholder-laptop {
  background: linear-gradient(135deg, #b0b0b8 0%, #909098 100%);
  border-radius: 12px;
  width: 80% !important;
  aspect-ratio: 16/10 !important;
  max-width: 400px !important;
}
.placeholder-tablet {
  background: linear-gradient(135deg, #2a2a2e 0%, #404045 100%);
  border-radius: 16px;
  width: 60% !important;
  aspect-ratio: 3/4 !important;
  max-width: 280px !important;
}
.placeholder-earbuds {
  background: linear-gradient(135deg, #e0d8f0 0%, #c8bcd8 100%);
  border-radius: 50%;
  width: 45% !important;
  aspect-ratio: 1 !important;
  max-width: 200px !important;
}
.placeholder-tradein {
  background: linear-gradient(135deg, #b8d0e8 0%, #90b8d8 100%);
  border-radius: 20px;
  width: 55% !important;
  aspect-ratio: 4/3 !important;
  max-width: 260px !important;
}

/* --- Carousel System --- */
.carousel-section {
  padding: 40px 0;
}
.carousel-section.alt-bg {
  background: var(--bg-secondary);
}
.carousel-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 16px;
  padding: 0 22px;
}
.carousel-header-full {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0;
}
.carousel-nav {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}
.carousel-nav button {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--text-primary);
}
.carousel-nav button:hover {
  background: var(--border-light);
}
.carousel-nav button:disabled {
  opacity: 0.3;
  cursor: default;
}
.carousel-nav button svg {
  width: 16px;
  height: 16px;
}

.carousel-track-wrapper {
  position: relative;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 0 22px;
  scroll-behavior: smooth;
}
.carousel-track::-webkit-scrollbar { display: none; }

/* --- Product Card --- */
.product-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.product-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.product-card .card-image {
  height: 260px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.product-card .card-image .card-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(8px);
  padding: 3px 8px;
  border-radius: 4px;
}
.product-card .card-body {
  padding: var(--card-padding);
}
.product-card .card-name {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 2px;
  line-height: 1.3;
}
.product-card .card-tagline {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 10px;
  line-height: 1.35;
}
.product-card .card-price {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}
.product-card .card-monthly {
  font-size: 12px;
  color: var(--text-secondary);
}
.product-card .card-ctas {
  margin-top: 12px;
  display: flex;
  gap: 16px;
}
.product-card .card-ctas a {
  font-size: 14px;
}

/* Card image backgrounds */
.card-bg-phone { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); }
.card-bg-laptop { background: linear-gradient(180deg, #fbfbfd 0%, #eef0f2 100%); }
.card-bg-laptop-dark { background: linear-gradient(180deg, #2d2d30 0%, #1d1d1f 100%); }
.card-bg-tablet { background: linear-gradient(180deg, #f0f0f5 0%, #e0e0e8 100%); }
.card-bg-headphones { background: linear-gradient(180deg, #f5f0ff 0%, #e8e0f5 100%); }
.card-bg-watch { background: linear-gradient(180deg, #f0f7f4 0%, #dde8e0 100%); }
.card-bg-accessory { background: linear-gradient(180deg, #f5f5f7 0%, #ececf0 100%); }
.card-bg-speaker { background: linear-gradient(180deg, #2d2d30 0%, #1d1d1f 100%); }
.card-bg-earbuds { background: linear-gradient(180deg, #fff5f0 0%, #f5e8dd 100%); }

/* Product icon placeholders in cards */
.card-icon {
  width: 120px;
  height: 120px;
  border-radius: 20px;
  opacity: 0.7;
}
.card-icon-phone { background: linear-gradient(135deg, #c0c0c5, #a0a0a8); border-radius: 24px; }
.card-icon-laptop { background: linear-gradient(135deg, #b0b0b8, #909098); border-radius: 12px; }
.card-icon-tablet { background: linear-gradient(135deg, #c8c8d0, #a8a8b0); border-radius: 16px; }
.card-icon-watch { background: linear-gradient(135deg, #b8c8c0, #98a898); border-radius: 28px; }
.card-icon-headphones { background: linear-gradient(135deg, #d0c8e0, #b8a8d0); border-radius: 24px; }
.card-icon-speaker { background: linear-gradient(135deg, #808088, #606068); border-radius: 50%; }
.card-icon-earbuds { background: linear-gradient(135deg, #e0d8f0, #c8bcd8); border-radius: 50%; }
.card-icon-accessory { background: linear-gradient(135deg, #c0c0c5, #a8a8b0); border-radius: 12px; }

/* --- Help & Info Cards --- */
.info-card {
  flex: 0 0 300px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.info-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.info-card .card-image {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-secondary);
}
.info-card .card-body {
  padding: var(--card-padding);
}
.info-card .card-icon-large {
  font-size: 48px;
  margin-bottom: 8px;
}
.info-card .card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.3;
}
.info-card .card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.4;
}
.info-card .card-link {
  display: inline-block;
  margin-top: 10px;
  font-size: 14px;
}

/* --- Product Icon Bar --- */
.product-icon-bar {
  padding: 20px 0;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-primary);
}
.product-icon-bar .icon-bar-scroll {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  justify-content: center;
  flex-wrap: nowrap;
}
.product-icon-bar .icon-bar-scroll::-webkit-scrollbar { display: none; }
.icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 20px;
  min-width: 90px;
  transition: opacity var(--transition-fast);
  cursor: pointer;
  text-decoration: none;
  color: var(--text-primary);
}
.icon-item:hover { opacity: 0.7; text-decoration: none; }
.icon-item .icon-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.icon-item .icon-label {
  font-size: 11px;
  font-weight: 400;
  text-align: center;
  white-space: nowrap;
}
.icon-item.active .icon-label {
  font-weight: 600;
}

/* --- Entertainment Tabs --- */
.entertainment-section {
  padding: var(--section-padding);
  background: var(--bg-primary);
}
.entertainment-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 20px;
  overflow-x: auto;
}
.entertainment-tabs::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 10px 24px;
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  white-space: nowrap;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  color: var(--text-primary);
  border-bottom-color: var(--text-primary);
}
.tab-content {
  display: none;
}
.tab-content.active {
  display: block;
  animation: fadeIn 300ms ease-out;
}
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.entertainment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.entertainment-card {
  border-radius: var(--radius-sm);
  overflow: hidden;
  position: relative;
  aspect-ratio: 3/4;
  cursor: pointer;
  transition: transform var(--transition-base);
}
.entertainment-card:hover { transform: scale(1.02); }
.entertainment-card .card-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
}
.entertainment-card .card-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 16px;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: #fff;
}
.entertainment-card .card-overlay .card-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
}
.entertainment-card .card-overlay .card-cta {
  font-size: 12px;
  opacity: 0.8;
}

/* Entertainment card backgrounds */
.ent-bg-1 { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.ent-bg-2 { background: linear-gradient(135deg, #0f3460, #533483); }
.ent-bg-3 { background: linear-gradient(135deg, #e94560, #0f3460); }
.ent-bg-4 { background: linear-gradient(135deg, #533483, #e94560); }
.ent-bg-5 { background: linear-gradient(135deg, #2d2d30, #4a4a50); }
.ent-bg-6 { background: linear-gradient(135deg, #1d3557, #457b9d); }
.ent-bg-7 { background: linear-gradient(135deg, #e63946, #457b9d); }
.ent-bg-8 { background: linear-gradient(135deg, #2a9d8f, #264653); }

/* --- Brand Collaboration --- */
.brand-collab {
  padding: var(--section-padding);
  background: var(--bg-primary);
}
.brand-collab-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #1d1d1f 0%, #2d2d30 100%);
  color: #fff;
  padding: 60px 50px;
  display: flex;
  align-items: center;
  gap: 60px;
  min-height: 400px;
}
.brand-collab-card .collab-content {
  flex: 1;
}
.brand-collab-card .collab-heading {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: 8px;
}
.brand-collab-card .collab-subtitle {
  font-size: 21px;
  color: rgba(255,255,255,0.7);
  margin-bottom: 16px;
}
.brand-collab-card .collab-desc {
  font-size: 15px;
  color: rgba(255,255,255,0.5);
  max-width: 420px;
  line-height: 1.5;
}
.brand-collab-card .collab-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.brand-collab-card .collab-placeholder {
  width: 280px;
  height: 280px;
  background: linear-gradient(135deg, #404045, #505058);
  border-radius: 50%;
  opacity: 0.6;
}

/* --- Quick Links --- */
.quick-links-section {
  padding: 40px 0;
  background: var(--bg-secondary);
}
.quick-links-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}
.quick-link-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: 980px;
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  font-size: 14px;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  text-decoration: none;
}
.quick-link-btn:hover {
  background: var(--border-light);
  text-decoration: none;
}
.quick-link-btn svg {
  width: 14px;
  height: 14px;
}

/* --- Sticky Section Navigation --- */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
  z-index: 900;
  padding: 0;
}
.section-nav .nav-scroll {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.section-nav .nav-scroll::-webkit-scrollbar { display: none; }
.section-nav .section-tab {
  padding: 12px 16px;
  font-size: 12px;
  font-weight: 400;
  color: var(--text-secondary);
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}
.section-nav .section-tab:hover {
  color: var(--text-primary);
}
.section-nav .section-tab.active {
  color: var(--text-primary);
  font-weight: 600;
  border-bottom-color: var(--text-primary);
}

/* --- Savings/Store Cards --- */
.savings-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.savings-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.savings-card .card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-secondary);
  font-size: 40px;
}
.savings-card .card-body {
  padding: var(--card-padding);
}
.savings-card .card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.3;
}
.savings-card .card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.4;
}
.savings-card .card-link {
  display: inline-block;
  margin-top: 10px;
  font-size: 14px;
}

/* --- Footer --- */
.site-footer {
  background: var(--bg-secondary);
  padding: 20px 0 30px;
  border-top: 1px solid var(--border-light);
  font-size: 12px;
  color: var(--text-secondary);
}
.footer-legal {
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 16px;
  line-height: 1.5;
}
.footer-nav-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 16px;
}
.footer-nav-col h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 10px;
}
.footer-nav-col ul li {
  margin-bottom: 6px;
}
.footer-nav-col ul li a {
  font-size: 12px;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}
.footer-nav-col ul li a:hover {
  color: var(--text-primary);
  text-decoration: none;
}
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}
.footer-bottom .footer-copyright {
  font-size: 12px;
}
.footer-bottom .footer-legal-links {
  display: flex;
  gap: 16px;
}
.footer-bottom .footer-legal-links a {
  font-size: 12px;
  color: var(--text-secondary);
}
.footer-bottom .footer-legal-links a:hover {
  color: var(--text-primary);
  text-decoration: none;
}

/* --- Experience / Setup Section --- */
.experience-section {
  padding: var(--section-padding);
}
.experience-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-secondary);
  padding: 50px;
  display: flex;
  align-items: center;
  gap: 50px;
  min-height: 360px;
}
.experience-card .exp-content {
  flex: 1;
}
.experience-card .exp-title {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.experience-card .exp-desc {
  font-size: 17px;
  color: var(--text-secondary);
  margin-bottom: 16px;
  max-width: 400px;
}
.experience-card .exp-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.experience-card .exp-placeholder {
  width: 240px;
  height: 180px;
  background: linear-gradient(135deg, var(--border-light), var(--border-color));
  border-radius: var(--radius-md);
}

/* --- Special Stores Section --- */
.special-stores {
  padding: var(--section-padding);
  background: var(--bg-primary);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
  .product-tile {
    min-height: 500px;
  }
  .entertainment-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .brand-collab-card {
    flex-direction: column;
    padding: 40px 30px;
    gap: 30px;
  }
  .experience-card {
    flex-direction: column;
    padding: 40px 30px;
    gap: 30px;
  }
  .footer-nav-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --nav-height: 44px;
  }

  .hero-section h1 { font-size: 36px; }
  .hero-section .hero-subtitle { font-size: 19px; }
  .category-hero h1 { font-size: 32px; }
  .section-heading h2 { font-size: 28px; }
  .section-heading .section-subtitle { font-size: 17px; }

  .top-nav .nav-links { display: none; }
  .top-nav .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(255,255,255,0.98);
    backdrop-filter: blur(20px);
    padding: 16px 22px;
    gap: 14px;
    border-bottom: 1px solid var(--border-light);
    z-index: 999;
  }
  .top-nav .nav-links.open a { font-size: 15px; }
  .nav-toggle { display: flex; }

  .product-tile { min-height: 420px; padding: 30px 20px 0; }
  .product-tile .tile-title { font-size: 28px; }
  .product-tile .tile-tagline { font-size: 17px; }
  .product-tile .tile-ctas { gap: 14px; }
  .product-tile .tile-ctas a { font-size: 15px; }

  .product-card { flex: 0 0 240px; }
  .info-card { flex: 0 0 260px; }
  .savings-card { flex: 0 0 240px; }

  .entertainment-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .carousel-track { padding: 0 16px; }
  .carousel-header { padding: 0 16px; }

  .brand-collab-card {
    padding: 30px 20px;
  }
  .brand-collab-card .collab-heading { font-size: 28px; }
  .brand-collab-card .collab-subtitle { font-size: 17px; }

  .experience-card {
    padding: 30px 20px;
  }
  .experience-card .exp-title { font-size: 24px; }

  /* Footer accordion on mobile */
  .footer-nav-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-nav-col {
    border-bottom: 1px solid var(--border-light);
  }
  .footer-nav-col h4 {
    padding: 12px 0;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    user-select: none;
  }
  .footer-nav-col h4::after {
    content: '';
    width: 10px;
    height: 10px;
    border-right: 1.5px solid var(--text-secondary);
    border-bottom: 1.5px solid var(--text-secondary);
    transform: rotate(45deg);
    transition: transform var(--transition-fast);
    flex-shrink: 0;
  }
  .footer-nav-col.expanded h4::after {
    transform: rotate(-135deg);
  }
  .footer-nav-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-base);
    padding: 0;
  }
  .footer-nav-col.expanded ul {
    max-height: 500px;
    padding-bottom: 12px;
  }
  .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }

  .hero-section { padding: 50px 0 40px; }
  .section-nav .section-tab { font-size: 11px; padding: 10px 12px; }
  .icon-item { padding: 8px 12px; min-width: 72px; }
  .icon-item .icon-circle { width: 42px; height: 42px; font-size: 16px; }
}

@media (max-width: 480px) {
  .entertainment-grid {
    grid-template-columns: 1fr 1fr;
  }
  .product-tile .tile-title { font-size: 24px; }
  .product-tile .tile-tagline { font-size: 15px; }
}

raw_arguments.content:
/* ============================================
   Orchard — Premium Tech E-Commerce Store
   Design System & Component Styles
   ============================================ */

/* --- Design Tokens --- */
:root {
  --bg-primary: #ffffff;
  --bg-secondary: #f5f5f7;
  --bg-tertiary: #fbfbfd;
  --text-primary: #1d1d1f;
  --text-secondary: #6e6e73;
  --text-tertiary: #86868b;
  --accent-blue: #0066cc;
  --accent-blue-hover: #004499;
  --border-color: #d2d2d7;
  --border-light: #e8e8ed;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.12);
  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 24px;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --nav-height: 48px;
  --section-padding: 60px 0;
  --card-padding: 24px;
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease-out;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-stack);
  font-size: 17px;
  line-height: 1.47;
  color: var(--text-primary);
  background: var(--bg-primary);
  overflow-x: hidden;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--accent-blue-hover); text-decoration: underline; }

img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Utility --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); border: 0;
}

.text-secondary { color: var(--text-secondary); }
.text-tertiary { color: var(--text-tertiary); }
.text-accent { color: var(--accent-blue); }
.text-center { text-align: center; }

/* --- Ribbon Banner --- */
.ribbon-banner {
  background: var(--bg-secondary);
  text-align: center;
  padding: 12px 22px;
  font-size: 14px;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-light);
}
.ribbon-banner a {
  color: var(--accent-blue);
  white-space: nowrap;
}

/* --- Top Navigation --- */
.top-nav {
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--nav-height);
}
.top-nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}
.top-nav .nav-logo {
  font-size: 20px;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}
.top-nav .nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
}
.top-nav .nav-links a {
  font-size: 12px;
  color: var(--text-primary);
  opacity: 0.8;
  transition: opacity var(--transition-fast);
  letter-spacing: 0;
}
.top-nav .nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}
.top-nav .nav-links a.active {
  opacity: 1;
  font-weight: 500;
}

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}
.nav-toggle span {
  display: block;
  width: 18px;
  height: 1.5px;
  background: var(--text-primary);
  transition: var(--transition-fast);
}

/* --- Hero Section --- */
.hero-section {
  padding: 80px 0 60px;
  text-align: center;
  background: var(--bg-primary);
}
.hero-section h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.07;
  margin-bottom: 8px;
}
.hero-section .hero-subtitle {
  font-size: 28px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: 20px;
  letter-spacing: -0.01em;
}
.hero-ctas {
  display: flex;
  gap: 24px;
  justify-content: center;
  flex-wrap: wrap;
}
.hero-ctas a {
  font-size: 17px;
  font-weight: 400;
}

/* --- Category Hero (Shop Pages) --- */
.category-hero {
  padding: 60px 0 40px;
  text-align: center;
  background: var(--bg-primary);
}
.category-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.08;
  margin-bottom: 6px;
}

/* --- Section Headings --- */
.section-heading {
  margin-bottom: 4px;
}
.section-heading h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}
.section-heading .section-subtitle {
  font-size: 21px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-top: 4px;
  letter-spacing: 0;
}
.section-heading .section-promo {
  font-size: 14px;
  color: var(--text-secondary);
  margin-top: 6px;
}
.section-heading .section-promo a {
  color: var(--accent-blue);
}

/* --- Product Grid (Homepage) --- */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 12px 0;
}
.product-tile {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 580px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 40px 30px 0;
  transition: transform var(--transition-base);
}
.product-tile:hover {
  transform: scale(1.005);
}
.product-tile .tile-content {
  position: relative;
  z-index: 2;
}
.product-tile .tile-badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.product-tile .tile-title {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: 4px;
}
.product-tile .tile-tagline {
  font-size: 21px;
  color: var(--text-secondary);
  margin-bottom: 16px;
  font-weight: 400;
}
.product-tile .tile-ctas {
  display: flex;
  gap: 20px;
  justify-content: center;
  margin-bottom: 24px;
}
.product-tile .tile-ctas a {
  font-size: 17px;
}
.product-tile .tile-image {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  position: relative;
  z-index: 1;
}
.product-tile .tile-image .product-placeholder {
  width: 70%;
  max-width: 380px;
  aspect-ratio: 3/4;
  border-radius: var(--radius-md);
  margin-bottom: -2px;
}

/* Tile background colors */
.tile-phone { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); color: var(--text-primary); }
.tile-laptop-neo { background: linear-gradient(180deg, #fbfbfd 0%, #eef0f2 100%); color: var(--text-primary); }
.tile-tablet-pro { background: linear-gradient(180deg, #1d1d1f 0%, #2d2d30 100%); color: #fff; }
.tile-tablet-pro .tile-tagline { color: rgba(255,255,255,0.7); }
.tile-laptop-pro { background: linear-gradient(180deg, #1d1d1f 0%, #2d2d30 100%); color: #fff; }
.tile-laptop-pro .tile-tagline { color: rgba(255,255,255,0.7); }
.tile-earbuds { background: linear-gradient(180deg, #f5f0ff 0%, #e8e0f5 100%); color: var(--text-primary); }
.tile-tradein { background: linear-gradient(180deg, #f0f7ff 0%, #ddeaf8 100%); color: var(--text-primary); }

/* Product placeholder shapes */
.placeholder-phone {
  background: linear-gradient(135deg, #c0c0c5 0%, #a0a0a8 50%, #888890 100%);
  border-radius: 30px;
  width: 55% !important;
  aspect-ratio: 9/19 !important;
  max-width: 220px !important;
}
.placeholder-laptop {
  background: linear-gradient(135deg, #b0b0b8 0%, #909098 100%);
  border-radius: 12px;
  width: 80% !important;
  aspect-ratio: 16/10 !important;
  max-width: 400px !important;
}
.placeholder-tablet {
  background: linear-gradient(135deg, #2a2a2e 0%, #404045 100%);
  border-radius: 16px;
  width: 60% !important;
  aspect-ratio: 3/4 !important;
  max-width: 280px !important;
}
.placeholder-earbuds {
  background: linear-gradient(135deg, #e0d8f0 0%, #c8bcd8 100%);
  border-radius: 50%;
  width: 45% !important;
  aspect-ratio: 1 !important;
  max-width: 200px !important;
}
.placeholder-tradein {
  background: linear-gradient(135deg, #b8d0e8 0%, #90b8d8 100%);
  border-radius: 20px;
  width: 55% !important;
  aspect-ratio: 4/3 !important;
  max-width: 260px !important;
}

/* --- Carousel System --- */
.carousel-section {
  padding: 40px 0;
}
.carousel-section.alt-bg {
  background: var(--bg-secondary);
}
.carousel-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 16px;
  padding: 0 22px;
}
.carousel-header-full {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0;
}
.carousel-nav {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}
.carousel-nav button {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--text-primary);
}
.carousel-nav button:hover {
  background: var(--border-light);
}
.carousel-nav button:disabled {
  opacity: 0.3;
  cursor: default;
}
.carousel-nav button svg {
  width: 16px;
  height: 16px;
}

.carousel-track-wrapper {
  position: relative;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 0 22px;
  scroll-behavior: smooth;
}
.carousel-track::-webkit-scrollbar { display: none; }

/* --- Product Card --- */
.product-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.product-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.product-card .card-image {
  height: 260px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.product-card .card-image .card-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(8px);
  padding: 3px 8px;
  border-radius: 4px;
}
.product-card .card-body {
  padding: var(--card-padding);
}
.product-card .card-name {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 2px;
  line-height: 1.3;
}
.product-card .card-tagline {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 10px;
  line-height: 1.35;
}
.product-card .card-price {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}
.product-card .card-monthly {
  font-size: 12px;
  color: var(--text-secondary);
}
.product-card .card-ctas {
  margin-top: 12px;
  display: flex;
  gap: 16px;
}
.product-card .card-ctas a {
  font-size: 14px;
}

/* Card image backgrounds */
.card-bg-phone { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); }
.card-bg-laptop { background: linear-gradient(180deg, #fbfbfd 0%, #eef0f2 100%); }
.card-bg-laptop-dark { background: linear-gradient(180deg, #2d2d30 0%, #1d1d1f 100%); }
.card-bg-tablet { background: linear-gradient(180deg, #f0f0f5 0%, #e0e0e8 100%); }
.card-bg-headphones { background: linear-gradient(180deg, #f5f0ff 0%, #e8e0f5 100%); }
.card-bg-watch { background: linear-gradient(180deg, #f0f7f4 0%, #dde8e0 100%); }
.card-bg-accessory { background: linear-gradient(180deg, #f5f5f7 0%, #ececf0 100%); }
.card-bg-speaker { background: linear-gradient(180deg, #2d2d30 0%, #1d1d1f 100%); }
.card-bg-earbuds { background: linear-gradient(180deg, #fff5f0 0%, #f5e8dd 100%); }

/* Product icon placeholders in cards */
.card-icon {
  width: 120px;
  height: 120px;
  border-radius: 20px;
  opacity: 0.7;
}
.card-icon-phone { background: linear-gradient(135deg, #c0c0c5, #a0a0a8); border-radius: 24px; }
.card-icon-laptop { background: linear-gradient(135deg, #b0b0b8, #909098); border-radius: 12px; }
.card-icon-tablet { background: linear-gradient(135deg, #c8c8d0, #a8a8b0); border-radius: 16px; }
.card-icon-watch { background: linear-gradient(135deg, #b8c8c0, #98a898); border-radius: 28px; }
.card-icon-headphones { background: linear-gradient(135deg, #d0c8e0, #b8a8d0); border-radius: 24px; }
.card-icon-speaker { background: linear-gradient(135deg, #808088, #606068); border-radius: 50%; }
.card-icon-earbuds { background: linear-gradient(135deg, #e0d8f0, #c8bcd8); border-radius: 50%; }
.card-icon-accessory { background: linear-gradient(135deg, #c0c0c5, #a8a8b0); border-radius: 12px; }

/* --- Help & Info Cards --- */
.info-card {
  flex: 0 0 300px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.info-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.info-card .card-image {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-secondary);
}
.info-card .card-body {
  padding: var(--card-padding);
}
.info-card .card-icon-large {
  font-size: 48px;
  margin-bottom: 8px;
}
.info-card .card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.3;
}
.info-card .card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.4;
}
.info-card .card-link {
  display: inline-block;
  margin-top: 10px;
  font-size: 14px;
}

/* --- Product Icon Bar --- */
.product-icon-bar {
  padding: 20px 0;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-primary);
}
.product-icon-bar .icon-bar-scroll {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  justify-content: center;
  flex-wrap: nowrap;
}
.product-icon-bar .icon-bar-scroll::-webkit-scrollbar { display: none; }
.icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 20px;
  min-width: 90px;
  transition: opacity var(--transition-fast);
  cursor: pointer;
  text-decoration: none;
  color: var(--text-primary);
}
.icon-item:hover { opacity: 0.7; text-decoration: none; }
.icon-item .icon-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}
.icon-item .icon-label {
  font-size: 11px;
  font-weight: 400;
  text-align: center;
  white-space: nowrap;
}
.icon-item.active .icon-label {
  font-weight: 600;
}

/* --- Entertainment Tabs --- */
.entertainment-section {
  padding: var(--section-padding);
  background: var(--bg-primary);
}
.entertainment-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 20px;
  overflow-x: auto;
}
.entertainment-tabs::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 10px 24px;
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  white-space: nowrap;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  color: var(--text-primary);
  border-bottom-color: var(--text-primary);
}
.tab-content {
  display: none;
}
.tab-content.active {
  display: block;
  animation: fadeIn 300ms ease-out;
}
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.entertainment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.entertainment-card {
  border-radius: var(--radius-sm);
  overflow: hidden;
  position: relative;
  aspect-ratio: 3/4;
  cursor: pointer;
  transition: transform var(--transition-base);
}
.entertainment-card:hover { transform: scale(1.02); }
.entertainment-card .card-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
}
.entertainment-card .card-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 16px;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: #fff;
}
.entertainment-card .card-overlay .card-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
}
.entertainment-card .card-overlay .card-cta {
  font-size: 12px;
  opacity: 0.8;
}

/* Entertainment card backgrounds */
.ent-bg-1 { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.ent-bg-2 { background: linear-gradient(135deg, #0f3460, #533483); }
.ent-bg-3 { background: linear-gradient(135deg, #e94560, #0f3460); }
.ent-bg-4 { background: linear-gradient(135deg, #533483, #e94560); }
.ent-bg-5 { background: linear-gradient(135deg, #2d2d30, #4a4a50); }
.ent-bg-6 { background: linear-gradient(135deg, #1d3557, #457b9d); }
.ent-bg-7 { background: linear-gradient(135deg, #e63946, #457b9d); }
.ent-bg-8 { background: linear-gradient(135deg, #2a9d8f, #264653); }

/* --- Brand Collaboration --- */
.brand-collab {
  padding: var(--section-padding);
  background: var(--bg-primary);
}
.brand-collab-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #1d1d1f 0%, #2d2d30 100%);
  color: #fff;
  padding: 60px 50px;
  display: flex;
  align-items: center;
  gap: 60px;
  min-height: 400px;
}
.brand-collab-card .collab-content {
  flex: 1;
}
.brand-collab-card .collab-heading {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: 8px;
}
.brand-collab-card .collab-subtitle {
  font-size: 21px;
  color: rgba(255,255,255,0.7);
  margin-bottom: 16px;
}
.brand-collab-card .collab-desc {
  font-size: 15px;
  color: rgba(255,255,255,0.5);
  max-width: 420px;
  line-height: 1.5;
}
.brand-collab-card .collab-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.brand-collab-card .collab-placeholder {
  width: 280px;
  height: 280px;
  background: linear-gradient(135deg, #404045, #505058);
  border-radius: 50%;
  opacity: 0.6;
}

/* --- Quick Links --- */
.quick-links-section {
  padding: 40px 0;
  background: var(--bg-secondary);
}
.quick-links-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}
.quick-link-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: 980px;
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  font-size: 14px;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  text-decoration: none;
}
.quick-link-btn:hover {
  background: var(--border-light);
  text-decoration: none;
}
.quick-link-btn svg {
  width: 14px;
  height: 14px;
}

/* --- Sticky Section Navigation --- */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
  z-index: 900;
  padding: 0;
}
.section-nav .nav-scroll {
  display: flex;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.section-nav .nav-scroll::-webkit-scrollbar { display: none; }
.section-nav .section-tab {
  padding: 12px 16px;
  font-size: 12px;
  font-weight: 400;
  color: var(--text-secondary);
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}
.section-nav .section-tab:hover {
  color: var(--text-primary);
}
.section-nav .section-tab.active {
  color: var(--text-primary);
  font-weight: 600;
  border-bottom-color: var(--text-primary);
}

/* --- Savings/Store Cards --- */
.savings-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.savings-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.savings-card .card-image {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-secondary);
  font-size: 40px;
}
.savings-card .card-body {
  padding: var(--card-padding);
}
.savings-card .card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.3;
}
.savings-card .card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.4;
}
.savings-card .card-link {
  display: inline-block;
  margin-top: 10px;
  font-size: 14px;
}

/* --- Footer --- */
.site-footer {
  background: var(--bg-secondary);
  padding: 20px 0 30px;
  border-top: 1px solid var(--border-light);
  font-size: 12px;
  color: var(--text-secondary);
}
.footer-legal {
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 16px;
  line-height: 1.5;
}
.footer-nav-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 16px;
}
.footer-nav-col h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 10px;
}
.footer-nav-col ul li {
  margin-bottom: 6px;
}
.footer-nav-col ul li a {
  font-size: 12px;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}
.footer-nav-col ul li a:hover {
  color: var(--text-primary);
  text-decoration: none;
}
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}
.footer-bottom .footer-copyright {
  font-size: 12px;
}
.footer-bottom .footer-legal-links {
  display: flex;
  gap: 16px;
}
.footer-bottom .footer-legal-links a {
  font-size: 12px;
  color: var(--text-secondary);
}
.footer-bottom .footer-legal-links a:hover {
  color: var(--text-primary);
  text-decoration: none;
}

/* --- Experience / Setup Section --- */
.experience-section {
  padding: var(--section-padding);
}
.experience-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-secondary);
  padding: 50px;
  display: flex;
  align-items: center;
  gap: 50px;
  min-height: 360px;
}
.experience-card .exp-content {
  flex: 1;
}
.experience-card .exp-title {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.experience-card .exp-desc {
  font-size: 17px;
  color: var(--text-secondary);
  margin-bottom: 16px;
  max-width: 400px;
}
.experience-card .exp-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.experience-card .exp-placeholder {
  width: 240px;
  height: 180px;
  background: linear-gradient(135deg, var(--border-light), var(--border-color));
  border-radius: var(--radius-md);
}

/* --- Special Stores Section --- */
.special-stores {
  padding: var(--section-padding);
  background: var(--bg-primary);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
  .product-tile {
    min-height: 500px;
  }
  .entertainment-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .brand-collab-card {
    flex-direction: column;
    padding: 40px 30px;
    gap: 30px;
  }
  .experience-card {
    flex-direction: column;
    padding: 40px 30px;
    gap: 30px;
  }
  .footer-nav-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --nav-height: 44px;
  }

  .hero-section h1 { font-size: 36px; }
  .hero-section .hero-subtitle { font-size: 19px; }
  .category-hero h1 { font-size: 32px; }
  .section-heading h2 { font-size: 28px; }
  .section-heading .section-subtitle { font-size: 17px; }

  .top-nav .nav-links { display: none; }
  .top-nav .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(255,255,255,0.98);
    backdrop-filter: blur(20px);
    padding: 16px 22px;
    gap: 14px;
    border-bottom: 1px solid var(--border-light);
    z-index: 999;
  }
  .top-nav .nav-links.open a { font-size: 15px; }
  .nav-toggle { display: flex; }

  .product-tile { min-height: 420px; padding: 30px 20px 0; }
  .product-tile .tile-title { font-size: 28px; }
  .product-tile .tile-tagline { font-size: 17px; }
  .product-tile .tile-ctas { gap: 14px; }
  .product-tile .tile-ctas a { font-size: 15px; }

  .product-card { flex: 0 0 240px; }
  .info-card { flex: 0 0 260px; }
  .savings-card { flex: 0 0 240px; }

  .entertainment-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .carousel-track { padding: 0 16px; }
  .carousel-header { padding: 0 16px; }

  .brand-collab-card {
    padding: 30px 20px;
  }
  .brand-collab-card .collab-heading { font-size: 28px; }
  .brand-collab-card .collab-subtitle { font-size: 17px; }

  .experience-card {
    padding: 30px 20px;
  }
  .experience-card .exp-title { font-size: 24px; }

  /* Footer accordion on mobile */
  .footer-nav-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-nav-col {
    border-bottom: 1px solid var(--border-light);
  }
  .footer-nav-col h4 {
    padding: 12px 0;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    user-select: none;
  }
  .footer-nav-col h4::after {
    content: '';
    width: 10px;
    height: 10px;
    border-right: 1.5px solid var(--text-secondary);
    border-bottom: 1.5px solid var(--text-secondary);
    transform: rotate(45deg);
    transition: transform var(--transition-fast);
    flex-shrink: 0;
  }
  .footer-nav-col.expanded h4::after {
    transform: rotate(-135deg);
  }
  .footer-nav-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-base);
    padding: 0;
  }
  .footer-nav-col.expanded ul {
    max-height: 500px;
    padding-bottom: 12px;
  }
  .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }

  .hero-section { padding: 50px 0 40px; }
  .section-nav .section-tab { font-size: 11px; padding: 10px 12px; }
  .icon-item { padding: 8px 12px; min-width: 72px; }
  .icon-item .icon-circle { width: 42px; height: 42px; font-size: 16px; }
}

@media (max-width: 480px) {
  .entertainment-grid {
    grid-template-columns: 1fr 1fr;
  }
  .product-tile .tile-title { font-size: 24px; }
  .product-tile .tile-tagline { font-size: 15px; }
}

