from html.parser import HTMLParser
class V(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append((tag, self.getpos()))
    def handle_endtag(self, tag):
        if tag in self.void: return
        if self.stack and self.stack[-1][0] == tag:
            self.stack.pop()
        else:
            print(f'  Mismatch: </{tag}> at line {self.getpos()[0]}, expected </{self.stack[-1][0]}>' if self.stack else f'  Extra: </{tag}>')
v = V()
v.feed(open('$f').read())
if v.stack:
    for t, pos in v.stack:
        print(f'  Unclosed: <{t}> at line {pos[0]}')
else:
    print('  OK')
"; done

